// ── Configuration (edit these) ──────────────────────────────────────
const ETH_RPC       = process.env.SCHLIEREN_ETH_RPC   || 'https://ethereum.publicnode.com';
const DEBUG_RPC     = process.env.SCHLIEREN_DEBUG_RPC || ''; // Alchemy/QuickNode/Geth w/ debug_*
const CORPUS_DIR    = process.env.SCHLIEREN_CORPUS_DIR || 'C:/projects/Schlieren/muscle/corpus';
const LIMIT_PER_RUN = parseInt(process.env.SCHLIEREN_LIMIT || '10');
const EXECUTE       = process.env.SCHLIEREN_EXECUTE !== 'false'; // set to 'false' to harvest-only
// ─────────────────────────────────────────────────────────────────────

const fs = require('fs');
const path = require('path');

// Ensure corpus dir exists
if (!fs.existsSync(CORPUS_DIR)) fs.mkdirSync(CORPUS_DIR, { recursive: true });

// Load checkpoint
const checkpointPath = path.join(CORPUS_DIR, '.checkpoint.json');
let lastBlock = 0;
if (fs.existsSync(checkpointPath)) {
  try {
    const cp = JSON.parse(fs.readFileSync(checkpointPath, 'utf8'));
    lastBlock = cp.lastProcessedBlock || 0;
  } catch {}
}

return [{
  json: {
    ethRpc:      ETH_RPC,
    debugRpc:    DEBUG_RPC,
    corpusDir:   CORPUS_DIR,
    limitPerRun: LIMIT_PER_RUN,
    execute:     EXECUTE,
    checkpointPath,
    lastBlock,
    harvested:   0,
    passed:      0,
    failed:      0,
    results:     [],
  }
}];

const prev     = $('Load Checkpoint').first().json;
const finalized = parseInt($input.first().json.result.number, 16);

// Start 5 blocks behind finalized (safety buffer)
const safeHead  = finalized - 5;
const startBlock = prev.lastBlock > 0
  ? Math.min(prev.lastBlock + 1, safeHead)
  : safeHead;

return [{
  json: {
    ...prev,
    finalizedBlock: finalized,
    startBlock,
    currentBlock:   startBlock,
  }
}];

// ── Known high-value protocol addresses (battle-tested corpus) ──────
const KNOWN_PROTOCOLS = new Set([
  '0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2', // WETH9
  '0x7a250d5630b4cf539739df2c5dacb4c659f2488d', // Uniswap V2 Router
  '0x68b3465833fb72a70ecdf485e0e4c7bd8665fc45', // Uniswap V3 Router2
  '0xe592427a0aece92de3edee1f18e0157c05861564', // Uniswap V3 SwapRouter
  '0x87870bca3f3fd6335c3f4ce8392d69350b4fa4e2', // Aave V3 Pool
  '0xba12222222228d8ba445958a75a0704d566bf2c8', // Balancer Vault
  '0xbebc44782c7db0a1a60cb6fe97d0b483032ff1c7', // Curve 3pool
  '0x1111111254eeb25477b68fb85ed929f73a960582', // 1inch v5
  '0xdef1c0ded9bec7f1a1670819833240f027b25eff', // 0x V4
  '0x00000000219ab540356cbb839cbe05303d7705fa', // ETH2 Deposit
]);

function isInteresting(tx) {
  const to     = (tx.to || '').toLowerCase();
  const data   = tx.input || '0x';

  // Skip: pure ETH transfers
  if (to && (data === '0x' || data === '')) return { keep: false, reason: 'plain_eth' };
  // Skip: contract creations (we can add these later)
  if (!tx.to) return { keep: true, reason: 'contract_creation' };
  // Keep: known protocols
  if (KNOWN_PROTOCOLS.has(to)) return { keep: true, reason: `protocol:${to.slice(0,10)}` };
  // Keep: ABI call (4-byte selector present)
  if (data.length >= 10) return { keep: true, reason: 'abi_call' };

  return { keep: false, reason: 'uninteresting' };
}

const prev     = $('Load Checkpoint').first().json;
const blockData = $input.first().json.result;
const txs = (blockData.transactions || []);

// Filter and output one item per interesting tx
const items = [];
for (const tx of txs) {
  const { keep, reason } = isInteresting(tx);
  if (!keep) continue;
  items.push({
    json: {
      ...prev,
      block:      blockData,
      tx,
      filterReason: reason,
    }
  });
}

console.log(`Block ${parseInt(blockData.number, 16)}: ${txs.length} txs → ${items.length} interesting`);
return items;

const receipt = $input.item.json.result;
if (!receipt) return []; // tx not mined yet — skip

const gasUsed = parseInt(receipt.gasUsed || '0x0', 16);

// Apply receipt-level filters (we now have real gas + logs)
const logs   = receipt.logs || [];
const status = receipt.status;

// Discard trivial executions (< 25k gas, no logs, success only)
if (gasUsed < 25000 && logs.length === 0 && status === '0x1') return [];

return [{
  json: {
    ...$input.item.json,
    receipt,
    gasUsed,
    logCount: logs.length,
    reverted: status === '0x0',
  }
}];

const fs   = require('fs');
const path = require('path');

const item    = $input.item.json;
const tx      = item.tx;
const block   = item.block;
const receipt = item.receipt;

// ── Determine prestate source ────────────────────────────────────────
let prestate = {};
let prestateMethod = 'eth_fallback';

if (item.debugPrestate) {
  // debug_traceTransaction result — normalize
  prestateMethod = 'debug_prestateTracer';
  for (const [addr, acct] of Object.entries(item.debugPrestate)) {
    const storage = {};
    for (const [slot, val] of Object.entries(acct.storage || {})) {
      const k = slot.startsWith('0x') ? slot : '0x' + slot;
      const v = val.startsWith('0x')  ? val  : '0x' + val;
      if (parseInt(v, 16) !== 0) storage[k] = v;
    }
    prestate[addr.toLowerCase()] = {
      balance: acct.balance || '0x0',
      nonce:   acct.nonce   || '0x0',
      code:    acct.code    || '0x',
      storage,
    };
  }
} else {
  // Fallback: sender + target from individual eth_* calls
  const senderBalance = item.senderBalance || '0x0';
  const senderNonce   = item.senderNonce   || '0x0';
  const targetCode    = item.targetCode    || '0x';
  const targetBalance = item.targetBalance || '0x0';
  const targetNonce   = item.targetNonce   || '0x0';

  if (tx.from) {
    prestate[tx.from.toLowerCase()] = {
      balance: senderBalance, nonce: senderNonce, code: '0x', storage: {}
    };
  }
  if (tx.to) {
    prestate[tx.to.toLowerCase()] = {
      balance: targetBalance, nonce: targetNonce, code: targetCode, storage: {}
    };
  }
}

// ── Detect fork from block number ─────────────────────────────────────
function detectFork(n) {
  if (n >= 22000000) return 'Osaka';
  if (n >= 20000000) return 'Prague';
  if (n >= 19426587) return 'Cancun';
  if (n >= 17034870) return 'Shanghai';
  if (n >= 15537394) return 'Paris';
  if (n >= 12965000) return 'London';
  return 'Berlin';
}

const blockNum = parseInt(block.number, 16);
const fork     = detectFork(blockNum);
const txHash   = tx.hash;

// ── Build ExecutionFixture ────────────────────────────────────────────
const fixture = {
  [`mainnet::${txHash}`]: {
    _provenance: {
      chain:          'mainnet',
      chainId:        '0x1',
      txHash,
      blockNumber:    block.number,
      blockNumberDec: blockNum,
      fork,
      prestateMethod,
      filterReason:   item.filterReason,
      harvestedAt:    new Date().toISOString(),
    },
    env: {
      currentCoinbase:      block.miner || '0x0000000000000000000000000000000000000000',
      currentGasLimit:      block.gasLimit      || '0x0',
      currentNumber:        block.number        || '0x0',
      currentTimestamp:     block.timestamp     || '0x0',
      currentBaseFee:       block.baseFeePerGas || '0x0',
      currentDifficulty:    block.difficulty    || '0x0',
      currentRandom:        block.mixHash       || ('0x' + '0'.repeat(64)),
      currentExcessBlobGas: block.excessBlobGas || '0x0',
    },
    pre: prestate,
    transaction: {
      nonce:               tx.nonce,
      gasPrice:            tx.gasPrice            || '0x0',
      maxFeePerGas:        tx.maxFeePerGas        || null,
      maxPriorityFeePerGas: tx.maxPriorityFeePerGas || null,
      gasLimit:            [tx.gas],
      to:                  tx.to,
      value:               [tx.value || '0x0'],
      data:                [tx.input || '0x'],
      sender:              tx.from,
      type:                tx.type || '0x0',
      accessList:          tx.accessList || [],
    },
    // Ground truth — what Ethereum mainnet already settled.
    // Schlieren diffs against this. No external EVM needed.
    realReceipt: {
      status:            receipt.status,
      gasUsed:           receipt.gasUsed,
      cumulativeGasUsed: receipt.cumulativeGasUsed,
      logCount:          (receipt.logs || []).length,
      contractAddress:   receipt.contractAddress || null,
    },
  }
};

// ── Write to corpus ───────────────────────────────────────────────────
const corpusDir  = item.corpusDir;
const date       = new Date().toISOString().slice(0, 10);
const safeHash   = txHash.slice(2, 12);
const filename   = `${date}-${blockNum}-${safeHash}.json`;
const outPath    = path.join(corpusDir, filename);
fs.writeFileSync(outPath, JSON.stringify(fixture, null, 2));

console.log(`Wrote: ${filename}  fork=${fork}  gas=${parseInt(receipt.gasUsed,16).toLocaleString()}  logs=${(receipt.logs||[]).length}`);

return [{
  json: {
    ...item,
    fixturePath: outPath,
    fixtureFile: filename,
    fork,
    prestateMethod,
    blockNum,
  }
}];

const output   = $input.item.json.stdout || '';
const passed   = output.includes('✓ All checks passed') || output.includes('MATCH');
const gasLine  = output.split('\n').find(l => l.includes('Gas used'));
const statusLine = output.split('\n').find(l => l.includes('Status'));

return [{
  json: {
    ...$input.item.json,
    schlierenPassed:  passed,
    schlierenOutput:  output.slice(-800), // last 800 chars for logging
    schlierenGasLine: gasLine?.trim(),
    schlierenStatus:  statusLine?.trim(),
  }
}];

const fs   = require('fs');
const path = require('path');

const items = $input.all();
if (!items.length) return [];

const first = items[0].json;
const corpusDir = first.corpusDir;
const checkpointPath = first.checkpointPath;

// Save checkpoint — furthest block processed
const maxBlock = Math.max(...items.map(i => i.json.blockNum || first.currentBlock));
fs.writeFileSync(checkpointPath, JSON.stringify({
  lastProcessedBlock: maxBlock,
  savedAt: new Date().toISOString(),
}, null, 2));

// Build run summary
const total   = items.length;
const passed  = items.filter(i => i.json.schlierenPassed === true).length;
const failed  = items.filter(i => i.json.schlierenPassed === false).length;
const harvest = items.filter(i => i.json.schlierenPassed === undefined).length;

const summaryLines = [
  `═══════════════════════════════════`,
  `  SCHLIEREN HARVEST RUN COMPLETE`,
  `  Fixtures written : ${total}`,
  `  Passed           : ${passed}`,
  `  Failed/Diagnostic: ${failed}`,
  `  Harvest-only     : ${harvest}`,
  `  Block checkpoint : ${maxBlock}`,
  `═══════════════════════════════════`,
];
console.log(summaryLines.join('\n'));

// Write run manifest
const date = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const manifest = {
  runAt:     new Date().toISOString(),
  fromBlock: first.startBlock,
  toBlock:   maxBlock,
  total, passed, failed, harvest,
  fixtures:  items.map(i => ({
    file:           i.json.fixtureFile,
    fork:           i.json.fork,
    txHash:         i.json.tx?.hash,
    reason:         i.json.filterReason,
    prestate:       i.json.prestateMethod,
    schlierenPassed: i.json.schlierenPassed,
    gasLine:        i.json.schlierenGasLine,
  }))
};
fs.writeFileSync(
  path.join(corpusDir, `manifest-${date}.json`),
  JSON.stringify(manifest, null, 2)
);

return [{ json: { summary: summaryLines.join('\n'), manifest } }];
